package it.penny.api.workspace;

import it.penny.api.PennyApplication;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.mock.web.MockMultipartFile;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.http.MediaType.APPLICATION_JSON;

@SpringBootTest(classes=PennyApplication.class)
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="PENNY_TEST_JDBC_URL",matches=".+")
class WorkspaceIntegrationTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->System.getenv("PENNY_TEST_JDBC_URL")+"?currentSchema=workspace_api");p.add("spring.datasource.username",()->System.getenv("PENNY_TEST_DB_USER"));p.add("spring.datasource.password",()->System.getenv("PENNY_TEST_DB_PASSWORD"));p.add("spring.flyway.schemas",()->"workspace_api");p.add("spring.jpa.hibernate.ddl-auto",()->"validate");}
 @Autowired JdbcTemplate db;@Autowired WebApplicationContext context;@Autowired ObjectMapper json;MockMvc mvc;
 final UsernamePasswordAuthenticationToken admin=new UsernamePasswordAuthenticationToken("workspace-admin@test.invalid","unused",List.of(new SimpleGrantedAuthority("ROLE_USER")));
 final UsernamePasswordAuthenticationToken other=new UsernamePasswordAuthenticationToken("workspace-other@test.invalid","unused",List.of(new SimpleGrantedAuthority("ROLE_USER")));
 final UsernamePasswordAuthenticationToken tech=new UsernamePasswordAuthenticationToken("workspace-tech@test.invalid","unused",List.of(new SimpleGrantedAuthority("ROLE_USER")));
 @BeforeEach void setup(){mvc=MockMvcBuilders.webAppContextSetup(context).build();db.execute("TRUNCATE penny_customers,penny_users RESTART IDENTITY CASCADE");for(String[] item:List.of(new String[]{"admin","ADMIN"},new String[]{"other","SALES"},new String[]{"tech","TECH"})){db.update("INSERT INTO penny_users(email,full_name,password_hash,must_change_password) VALUES (?,?,'unused',false)","workspace-"+item[0]+"@test.invalid",item[0]);db.update("INSERT INTO penny_user_roles SELECT u.id,r.id FROM penny_users u CROSS JOIN penny_roles r WHERE u.email=? AND r.code=?","workspace-"+item[0]+"@test.invalid",item[1]);}db.update("INSERT INTO penny_customers(id,kind,name,lifecycle_status) VALUES (1,'COMPANY','Alpha','CUSTOMER'),(2,'COMPANY','Beta','CUSTOMER')");}
 @Test void remindersAreOwnerScopedAndHaveExplicitTransitions() throws Exception {var r=mvc.perform(post("/api/workspace/notifications").principal(admin).contentType(APPLICATION_JSON).content("{\"message\":\"Chiama cliente\",\"dueOn\":\"2026-11-15\",\"customerId\":1}")).andExpect(status().isOk()).andReturn();long id=json.readTree(r.getResponse().getContentAsString()).path("id").asLong();mvc.perform(get("/api/workspace/notifications").principal(other)).andExpect(jsonPath("$.total").value(0));mvc.perform(put("/api/workspace/notifications/"+id).principal(other).contentType(APPLICATION_JSON).content("{\"status\":\"READ\"}")).andExpect(status().isNotFound());mvc.perform(put("/api/workspace/notifications/"+id).principal(admin).contentType(APPLICATION_JSON).content("{\"status\":\"READ\"}")).andExpect(status().isOk());assertEquals("READ",db.queryForObject("SELECT status FROM penny_notifications WHERE id=?",String.class,id));mvc.perform(put("/api/workspace/notifications/"+id).principal(admin).contentType(APPLICATION_JSON).content("{\"status\":\"CANCELLED\"}")).andExpect(status().isOk());}
 @Test void privateUploadsSanitizeNamesAndEnforceCustomerOrderAndRbac() throws Exception {long order=db.queryForObject("INSERT INTO penny_sales_orders(customer_id,order_number,sold_on) VALUES (2,'B-01','2026-10-30') RETURNING id",Long.class);var file=new MockMultipartFile("file","../../report.pdf","text/html","%PDF-1.7 test".getBytes());mvc.perform(multipart("/api/workspace/documents").file(file).param("customerId","1").param("saleOrderId",String.valueOf(order)).principal(admin)).andExpect(status().isBadRequest());var r=mvc.perform(multipart("/api/workspace/documents").file(file).param("customerId","1").principal(admin)).andExpect(status().isOk()).andReturn();long id=json.readTree(r.getResponse().getContentAsString()).path("id").asLong();mvc.perform(get("/api/workspace/documents/"+id+"/download").principal(tech)).andExpect(status().isForbidden());mvc.perform(get("/api/workspace/documents/"+id+"/download").principal(admin)).andExpect(status().isOk()).andExpect(header().string("Content-Type","application/pdf")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(content().bytes(file.getBytes()));assertEquals("report.pdf",db.queryForObject("SELECT filename FROM penny_documents WHERE id=?",String.class,id));mvc.perform(get("/api/workspace/documents").principal(admin)).andExpect(jsonPath("$.items[0].content").doesNotExist());mvc.perform(delete("/api/workspace/documents/"+id).principal(admin)).andExpect(status().isOk());mvc.perform(get("/api/workspace/documents/"+id+"/download").principal(admin)).andExpect(status().isNotFound());assertNotNull(db.queryForObject("SELECT content FROM penny_documents WHERE id=?",byte[].class,id));mvc.perform(post("/api/workspace/documents/"+id+"/restore").principal(admin)).andExpect(status().isOk());mvc.perform(get("/api/workspace/documents/"+id+"/download").principal(admin)).andExpect(status().isOk());}
 @Test void linkedDocumentsRejectProductsAndRecordsOwnedByAnotherCustomer() throws Exception {long product=db.queryForObject("INSERT INTO penny_installed_products(customer_id,category,name) VALUES (2,'SOFTWARE','Other customer product') RETURNING id",Long.class);long record=db.queryForObject("INSERT INTO penny_customer_records(customer_id,kind,name,status) VALUES (2,'TRAINING','Other customer course','PLANNED') RETURNING id",Long.class);var file=new MockMultipartFile("file","test.pdf","application/pdf","%PDF-1.7".getBytes());mvc.perform(multipart("/api/workspace/documents").file(file).param("customerId","1").param("installedProductId",String.valueOf(product)).principal(admin)).andExpect(status().isBadRequest());mvc.perform(multipart("/api/workspace/documents").file(file).param("customerId","1").param("recordId",String.valueOf(record)).principal(admin)).andExpect(status().isBadRequest());mvc.perform(multipart("/api/workspace/documents").file(file).param("customerId","2").param("recordId",String.valueOf(record)).param("installedProductId",String.valueOf(product)).principal(admin)).andExpect(status().isOk());}
 @Test void unsafeContentDownloadsAsOpaqueBytesAndOversizeIsRejected() throws Exception {var html=new MockMultipartFile("file","page.html","image/png","<script>alert(1)</script>".getBytes());var r=mvc.perform(multipart("/api/workspace/documents").file(html).param("customerId","1").principal(admin)).andExpect(status().isOk()).andReturn();long id=json.readTree(r.getResponse().getContentAsString()).path("id").asLong();mvc.perform(get("/api/workspace/documents/"+id+"/download").principal(admin)).andExpect(header().string("Content-Type","application/octet-stream"));mvc.perform(multipart("/api/workspace/documents").file(new MockMultipartFile("file","big.bin","application/octet-stream",new byte[5242881])).param("customerId","1").principal(admin)).andExpect(status().isBadRequest());}
 @Test void dueAlertsRespectProductPermissions() throws Exception {db.update("INSERT INTO penny_installed_products(customer_id,category,name,license_expires_on) VALUES (1,'SOFTWARE','Private product','2020-01-01')");long user=db.queryForObject("SELECT id FROM penny_users WHERE email=?",Long.class,other.getName());db.update("INSERT INTO penny_user_permissions(user_id,permission_code,effect) VALUES (?,'PRODUCTS_READ','DENY')",user);mvc.perform(get("/api/workspace/notifications/due-alerts").principal(other)).andExpect(jsonPath("$.items").isEmpty());mvc.perform(get("/api/workspace/notifications/due-alerts").principal(admin)).andExpect(jsonPath("$.items[0].message").value("Private product"));}
}
